		envAzureDevOpsUserName, envAzureDevOpsPAT, envAzureDevOpsOrgs, envAzureDevOpsCompare, envAzureDevOpsBackupLFS,
		envSourcehutToken, envSourcehutAPIURL,
	}
	pool := []string{"\x00unset", "\x00unset", "", " ", "refs", "REFS", "Refs", "clone", "yes", "true", "no", "Org1,Org2", "3", "x"}
	r := rand.New(rand.NewSource(42))
	var out bytes.Buffer
	old := logger
	defer func() { logger = old }()
	provs := make([]string, 0)
	for p := range enabledProviderAuth {
		provs = append(provs, p)
	}
	sort.Strings(provs)
	for i := 0; i < 20000; i++ {
		for _, v := range vars {
			_ = os.Unsetenv(v)
			_ = os.Unsetenv(v + "_FILE")
			val := pool[r.Intn(len(pool))]
			if val != "\x00unset" {
				_ = os.Setenv(v, val)
			}
		}
		var buf bytes.Buffer
		logger = log.New(&buf, "", 0)
		displayStartupConfig()
		fmt.Fprintf(&out, "#%d display:\n%s", i, buf.String())
		err := checkProvidersDefined()
		if err == nil {
			fmt.Fprintf(&out, "#%d cpd: nil\n", i)
		} else {
			lines := strings.Split(err.Error(), "\n")
			sort.Strings(lines)
			fmt.Fprintf(&out, "#%d cpd: %q\n", i, lines)
		}
		for _, p := range provs {
			n, perr := checkProvider(p)
			fmt.Fprintf(&out, "#%d cp %s: %d %v\n", i, p, n, perr)
		}
	}
	for _, v := range vars {
		_ = os.Unsetenv(v)
	}
	if err := os.WriteFile(os.Getenv("ZZ_OUT"), out.Bytes(), 0o600); err != nil {
		t.Fatal(err)
	}
}
EOF
